1	// Splices climb batch 10's MANIFEST block into a scratch copy of the workflow script and checks it, in the form of
2	// explorations/compile-ladder/plan-9/manifest/check9.js: node --check on the original and the spliced copy; the
3	// spliced copy parsed as the body of an async function, as the Workflow harness parses it (FACTS, "node --check does
4	// not check the batch script as the Workflow harness parses it ..."); every line outside the block byte-identical;
5	// the launch value refused when unset; the rungs, their order, the scatter and the entries' fields; each tail equal to
6	// its rung's section of the record followed by its briefing's reasons, one per key in order; no backtick or non-ASCII
7	// character in any string the agents read; each checks list a sub-list of its briefing; no tail or intro asking for a
8	// test citation to be re-anchored (the rule went at 2040cd056); no tail, intro or skeptic paragraph asking a skeptic to
9	// see the test fail again, rebuild or re-run a stage (POSITIONS.md, Nothing is built or run twice on the same code); the
10	// record's section 7 holds no copy of the block. Its last line counts the problems. Reads $OUT10/manifest10.js
11	// (gen10.py's output) and writes the spliced copy beside it. It splices nothing into the tracked script.
12	//   node check10.js [RECORD]      RECORD defaults to explorations/coordinator/CLIMB-BATCH-10.md
13	const fs = require('fs')
14	const cp = require('child_process')
15	const path = require('path')
16	const ROOT = process.env.FORTRESS_HOME || path.resolve(__dirname, '../../../..')
17	const HERE = process.env.OUT10 || path.join(ROOT, 'tmp')
18	const SRC = path.join(ROOT, 'explorations/coordinator/climb-batch-workflow.js')
19	const REC = process.argv[2] || path.join(ROOT, 'explorations/coordinator/CLIMB-BATCH-10.md')
20	const block = fs.readFileSync(path.join(HERE, 'manifest10.js'), 'utf8')
21	const orig = fs.readFileSync(SRC, 'utf8')
22	const lines = orig.split('\n')
23	const mIdx = lines.findIndex(l => l.startsWith('// MANIFEST - the coordinator replaces'))
24	const start = mIdx - 1
25	if (!/^\/\/ =+$/.test(lines[start])) throw new Error('no rule above MANIFEST')
26	const end = lines.findIndex(l => l.startsWith('// =========================== END MANIFEST'))
27	console.log('original script: MANIFEST block is lines', start + 1, 'to', end, 'of', lines.length)
28	const pre = lines.slice(0, start).join('\n'), post = lines.slice(end).join('\n')
29	const spliced = pre + '\n' + block + post
30	const out = path.join(HERE, 'wf-spliced-10.js')
31	fs.writeFileSync(out, spliced)
32	let bad = 0
33	if (!spliced.startsWith(pre + '\n') || !spliced.endsWith(post)) { bad++; console.log('outside the block differs') }
34	for (const f of [SRC, out]) {
35	  const r = cp.spawnSync('node', ['--check', f], { encoding: 'utf8' })
36	  console.log('node --check', path.basename(f), 'exit', r.status, r.stderr.trim().slice(0, 300))
37	  if (r.status !== 0) bad++
38	}
39	const AsyncFunction = Object.getPrototypeOf(async function () {}).constructor
40	for (const [name, text] of [['original', orig], ['spliced', spliced]]) {
41	  // the harness takes the script's one export (export const meta) out before it runs the rest as a function body
42	  try { new AsyncFunction('args', 'agent', 'pipeline', 'parallel', 'log', text.replace(/^export const meta/m, 'const meta')); console.log('parses as an async function body, its export taken out:', name) }
43	  catch (e) { bad++; console.log('does NOT parse as an async function body:', name, e.message) }
44	}
45	// the manifest part, evaluated with the script's own key validation and scatter order
46	const sl = spliced.split('\n')
47	const s2 = sl.findIndex(l => l.startsWith('// MANIFEST - the coordinator replaces')) - 1
48	const e2 = sl.findIndex(l => l.startsWith('// =========================== END MANIFEST'))
49	const manifest = sl.slice(s2, e2).join('\n')
50	const valStart = sl.findIndex(l => l.startsWith('const LOOKUP_TOOL = '))
51	const valEnd = sl.findIndex(l => l.startsWith('const keysOf = '))
52	const validation = sl.slice(valStart, valEnd + 1).join('\n')
53	const scatterLine = sl.find(l => l.startsWith('const SCATTER = '))
54	function evalWith(ledger) {
55	  let m = manifest
56	  if (ledger !== null) m = m.replace(/^const LEDGER_FROM = null/m, 'const LEDGER_FROM = ' + ledger)
57	  const f = new Function(m + '\n' + validation + '\n' + scatterLine + '\nreturn { BATCH, BATCH_RECORD, RUNGS, SCATTER, BATCH_INTRO, BATCH_OVERLAPS, LEDGER_FROM }')
58	  return f()
59	}
60	try { evalWith(null); bad++; console.log('LEDGER_FROM unset: did NOT throw (bad)') } catch (e) { console.log('LEDGER_FROM unset: throws:', e.message) }
61	const REASONS_HEAD = '**Your briefing, entry by entry.**'
62	const rec = fs.readFileSync(REC, 'utf8')
63	const s3 = rec.slice(rec.indexOf('\n## 3. The rungs\n'), rec.indexOf('\n## 4. '))
64	function section(id) {
65	  const re = new RegExp('^### ' + id + '\\. .*$', 'm')
66	  const m = re.exec(s3); if (!m) throw new Error('no section ' + id)
67	  const rest = s3.slice(m.index + m[0].length)
68	  const nx = rest.search(/^### [A-Z]\. /m)
69	  return (nx < 0 ? rest : rest.slice(0, nx)).replace(/^\n+|\n+$/g, '').replace(/`/g, '')
70	}
71	const r = evalWith(610)
72	const ids = r.RUNGS.map(x => x.id).join(', ')
73	const stage = r.RUNGS.filter(x => x.testIsStage).map(x => x.id).join(', ')
74	console.log('batch ' + r.BATCH + ', rungs ' + ids + ', scatter ' + r.SCATTER.map(x => x.id).join(', ') + ', testIsStage ' + stage + ', LEDGER_FROM ' + r.LEDGER_FROM + ', intro ' + r.BATCH_INTRO.length + ' chars, overlaps ' + r.BATCH_OVERLAPS.length + ' chars')
75	if (r.BATCH !== '10' || ids !== 'W, C, G, N' || r.SCATTER.map(x => x.id).join('') !== 'CNGW' || stage !== 'G, N') { bad++; console.log('  batch, rungs, scatter or testIsStage not as the record says') }
76	if (r.RUNGS.some(x => x.expectedCheckerCount !== undefined || x.expectedCheckerCrash !== undefined || x.landsOnlyWith)) { bad++; console.log('  a rung declares a count, a crash or landsOnlyWith, which the record does not') }
77	const reanchor = /re-anchor/i
78	const rerun = /sees it fail again|re-?run by the skeptic|skeptic re-?runs|run the stage yourself|skeptic rebuilds/i
79	for (const x of r.RUNGS) {
80	  const tl = x.tail.split('\n')
81	  const rh = tl.findIndex(l => l.startsWith(REASONS_HEAD))
82	  if (rh < 0) { bad++; console.log('  tail ' + x.id + ' has no reasons block'); continue }
83	  const body = tl.slice(7, rh - 1).join('\n')
84	  const want = section(x.id)
85	  if (body !== want || tl[rh - 1] !== '') { bad++; console.log('  tail ' + x.id + ' differs from its section') }
86	  const reasons = tl.slice(rh + 1, tl.length - 1)
87	  const keys = x.briefing || []
88	  if (reasons.length !== keys.length || !keys.every((k, i) => reasons[i].startsWith('- ' + k + ': ') && reasons[i].length > k.length + 6)) { bad++; console.log('  tail ' + x.id + ': the reasons are not one line per briefing key, in order') }
89	  if (tl[tl.length - 1] !== '') { bad++; console.log('  tail ' + x.id + ' does not end with an empty line') }
90	  for (const [name, text] of [['tail ' + x.id, x.tail], ['blurb ' + x.id, x.blurb]]) {
91	    if (/[^\x00-\x7f]/.test(text) || /`/.test(text)) { bad++; console.log('  ' + name + ' holds a backtick or non-ASCII') }
92	    if (reanchor.test(text)) { bad++; console.log('  ' + name + ' asks for a re-anchoring') }
93	    if (rerun.test(text)) { bad++; console.log('  ' + name + ' asks a skeptic to see a failure again, rebuild or re-run') }
94	  }
95	  const sk = tl.find(l => l.startsWith('**For the skeptic.**')) || ''
96	  if (!sk || /\bre-?run\b|\brebuild|\bant compileAll\b/i.test(sk)) { bad++; console.log('  ' + x.id + ': no For the skeptic paragraph, or it asks for a re-run or a build') }
97	  if (!(x.checks || []).every(k => x.briefing.includes(k))) { bad++; console.log('  checks not a sub-list: ' + x.id) }
98	  if (!x.path || !x.branch || x.branch !== 'wip/' + x.slug) { bad++; console.log('  ' + x.id + ': path or branch missing, or the branch is not wip/<slug>') }
99	  console.log('  ' + x.id + ': tail ' + tl.length + ' lines, briefing ' + keys.length + ' keys, checks ' + (x.checks || []).length + ' keys, ' + x.path + ' on ' + x.branch)
100	}
101	for (const [name, text] of [['intro', r.BATCH_INTRO], ['overlaps', r.BATCH_OVERLAPS]]) {
102	  if (/[^\x00-\x7f]/.test(text) || /`/.test(text)) { bad++; console.log('  ' + name + ' holds a backtick or non-ASCII') }
103	  if (reanchor.test(text)) { bad++; console.log('  ' + name + ' asks for a re-anchoring') }
104	  if (rerun.test(text)) { bad++; console.log('  ' + name + ' asks a skeptic to see a failure again, rebuild or re-run') }
105	}
106	// the record's section 7 names the generator and holds no copy of the block
107	const i7 = rec.indexOf('\n## 7. The manifest\n'), e7 = rec.indexOf('\n## 8. ', i7)
108	const s7 = i7 < 0 || e7 < 0 ? '' : rec.slice(i7, e7)
109	if (!s7 || s7.includes('```') || s7.includes('const RUNGS') || !s7.includes('gen10.py')) { bad++; console.log('the record\'s section 7 is not the one sentence naming gen10.py, or holds a copy of the block') }
110	else console.log('the record\'s section 7 names gen10.py and holds no copy of the block')
111	console.log('problems:', bad)
112
